draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two stick figures
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 100);
  ctx.lineTo(W/4 - 20, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 100);
  ctx.lineTo(W/4 + 20, H/2 + 120);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 100);
  ctx.lineTo(W - W/4 - 20, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 100);
  ctx.lineTo(W - W/4 + 20, H/2 + 120);
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20 * Math.sin(t), H/2);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t + Math.PI), H/2);
  ctx.stroke();

  ctx.restore();
}
